 $session=['workspace_id'=>$wid,'user_id'=>$user,'user_name'=>'Contact race','user_role'=>'owner','auth_version'=>1];$_SESSION=$session;$project=defaultProject($wid);
 $id=createLead(leadValues(['name'=>'Contact race','phone'=>'+254700001111']),uid(),$project)['id'];$original=leadContactRows($wid,$id)[0];
