 foreach($workers as [$proc,$pipes]){fwrite($pipes[0],"GO\n");fflush($pipes[0]);fclose($pipes[0]);}$out=[];foreach($workers as [$proc,$pipes]){$raw=stream_get_contents($pipes[1]);$errors=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);if(proc_close($proc)!==0)throw new RuntimeException($errors);$out[]=json_decode(trim($raw),true);}$workers=[];
 $codes=array_column($out,'status');sort($codes);rc($codes===[200,409],'simultaneous contact editors yield one commit and one conflict');$rows=leadContactRows($wid,$id);rc(count($rows)===2,'losing contact batch leaves no partial row');rc(count(array_filter($rows,fn($row)=>$row['is_primary']))===1,'concurrent primary changes preserve exactly one primary');rc(in_array($original['id'],array_column($rows,'id'),true),'concurrent adds retain the original contact');rc((int)query("SELECT COUNT(*) FROM activities WHERE workspace_id=? AND kind='contacts_updated'",[$wid])->fetchColumn()===1,'losing contact batch leaves no partial history');
